// Scoped to this sample version and selected image; not a blanket library claim.
const recipeVerification=Object.freeze({dishSlug:'lentil-bolognese',version:'basic',image:'kitchen-assets/lentil-bolognese.png',creatorCooked:true,imageCompared:false});
function verificationKeys(record){return [record.creatorCooked?'cookedLabel':'notConfirmed',record.creatorCooked&&record.imageCompared?'verifiedLabel':'imagePending'];}
function aiLink(label,classes=''){return `<button type="button" class="text-link ${classes}" data-action="about-ai" aria-haspopup="dialog" aria-controls="ai-dialog">${label}</button>`;}
function verificationMarkup(){const [cooked,imageStatus]=verificationKeys(recipeVerification);return `<div class="verification"><strong>${t(cooked)}</strong><span aria-hidden="true">·</span>${aiLink(t(imageStatus))}</div>`;}
const categoryIds=['all','potatoes','rice','pasta','noodles','lentils','vegetables','bread'];
const state={lang:'en',theme:'light',category:'all',query:'',servings:2,checked:new Set(),section:'ingredients',step:0,timerRemaining:720,timerEnd:null,timerStarted:false,sectionScroll:{ingredients:0,method:0}};
const app=document.querySelector('#app');
const dialog=document.querySelector('#ingredient-dialog');
const wide=matchMedia('(min-width:900px)');
const t=key=>strings[state.lang][key];
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>location.hash.split('/')[0]==='#explore'?'network':tomatoRoute()?location.hash.split('/')[0].slice(1):['recipe','cook','complete'].includes(location.hash.slice(1))?location.hash.slice(1):'library';
const image=(name,alt,extra='')=>`<img src="kitchen-assets/${name}.png" width="1536" height="1024" alt="${escapeHTML(alt)}" ${extra}>`;
const dishPhoto=()=>image('lentil-bolognese',t('fullDish'));
const ingredientPhoto=(small=false)=>`<figure class="ingredients-photo">${image('ingredients',t('ingredientNames').join(', '),'loading="lazy"')}<figcaption>${aiLink(t('ai'),'ingredient-credit')}${small?'':t('pictureNote')}</figcaption></figure>`;
const button=(text,action,classes='',attrs='')=>`<button type="button" class="button ${classes}" data-action="${action}" ${attrs}>${text}</button>`;
const footer=()=>`<footer class="page-foot"><span>${t('footer')}</span><span>${t('footerNote')}</span>${aiLink(t('aiLink'))}</footer>`;
const review=()=>`<details class="review-note"><summary>${t('reviewTitle')}</summary><p>${t('reviewBody')}</p></details>`;
function announce(message){document.querySelector('#announcement').textContent=message;}
function header(){document.querySelector('.ai-header-link').textContent=t('aiLink');document.documentElement.lang=state.lang;document.documentElement.dataset.theme=state.theme;document.querySelector('#draft-banner').textContent=t('draft');document.querySelector('.skip').textContent=t('skip');document.querySelector('#language').textContent=state.lang==='en'?'DE':'EN';document.querySelector('#language').setAttribute('aria-label',state.lang==='en'?'Switch to German':'Zu Englisch wechseln');document.querySelector('#theme').setAttribute('aria-label',t('theme'));document.querySelector('#theme').setAttribute('aria-pressed',String(state.theme==='dark'));document.querySelector('#navigation').innerHTML=[['library',t('browse')],['explore',networkText('nav')],['recipe',t('sample')],['cook',t('cooking')]].map(([page,label])=>`<a href="#${page}" ${route()===(page==='explore'?'network':page)?'aria-current="page"':''}>${label}</a>`).join('');}
function meta(){return `<div class="recipe-meta"><span>${t('five')}</span><span>${t('time')}</span><span>${t('vegetarian')}</span></div>${verificationMarkup()}`;}
function ingredients(prefix){return `<ul class="ingredients" aria-label="${t('checklist')}">${t('ingredientNames').map((name,i)=>{const n=[220,150,450,1,1][i]*state.servings/2;const q=new Intl.NumberFormat(state.lang,{maximumFractionDigits:2}).format(n);return `<li><label for="${prefix}-${i}"><input id="${prefix}-${i}" type="checkbox" data-ingredient="${i}" ${state.checked.has(i)?'checked':''}><span class="ingredient-name">${name}</span><span class="quantity">${q} ${i<3?'g':t('tsp')}</span></label></li>`;}).join('')}</ul>`;}
function servings(){return `<div class="servings"><button type="button" data-action="less" aria-label="${t('less')}" ${state.servings<=1?'disabled':''}>−</button><span class="serving-count">${state.servings}</span><button type="button" data-action="more" aria-label="${t('more')}" ${state.servings>=8?'disabled':''}>+</button></div>`;}
function renderLibrary(){app.innerHTML=`<main id="content" class="shell"><section class="intro"><div><p class="eyebrow">${t('welcome')}</p><h1>${t('title')}</h1></div><p>${t('intro')}</p></section><div class="ingredient-picker" role="group" aria-label="${t('ingredients')}">${categoryIds.map((id,i)=>`<button type="button" data-category="${id}" aria-pressed="${state.category===id}">${t('categories')[i]}</button>`).join('')}</div><div class="library-tools"><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">${t('search')}</span><input id="search" type="search" value="${escapeHTML(state.query)}" placeholder="${t('searchPlaceholder')}"></label><p class="result-note" id="result-count" role="status"></p></div><div id="results"></div><section class="kitchen-note"><div><p class="eyebrow">${t('welcome')}</p><h2>${t('noteTitle')}</h2><p>${t('noteBody')}</p></div><figure>${image('ingredients',t('ingredientNames').join(', '),'loading="lazy"')}<figcaption><strong>${t('gatherTitle')}</strong>${t('gatherBody')}<br><a href="#recipe" data-open-ingredients>${t('gatherLink')} →</a>${aiLink(t('ai'),'ingredient-credit')}</figcaption></figure></section>${footer()}</main>`;updateResults();}
function updateResults(){const match=['all','pasta','lentils'].includes(state.category)&&(!state.query.trim()||['lentil bolognese spaghetti pasta red lentils tomato sauce salt herbs linsen bolognese spaghetti pasta rote linsen tomatensauce salz kräuter',...t('ingredientNames')].join(' ').toLowerCase().includes(state.query.trim().toLowerCase()));document.querySelector('#result-count').textContent=t(match?'one':'zero');document.querySelector('#results').innerHTML=match?`<article class="featured"><figure class="featured-image"><a class="featured-image-link" href="#recipe" aria-label="${t('explore')}">${dishPhoto()}</a>${aiLink(t('ai'),'photo-credit')}</figure><div class="feature-copy"><p class="eyebrow">${t('pick')}</p><h2>${t('fullDish')}</h2><p>${t('desc')}</p>${meta()}<p class="learn-line">${t('practice')}</p><a class="button" href="#recipe">${t('explore')} <span aria-hidden="true">→</span></a><p class="small" style="margin-top:12px">${t('sourceNote')}</p></div></article>`:`<section class="empty"><h2>${t('emptyTitle')}</h2><p>${t('emptyBody')}</p>${button(t('clear'),'clear')}</section>`;}
function renderRecipe(){app.innerHTML=`<main id="content"><div class="shell"><a href="#library" class="back">← ${t('back')}</a><section class="recipe-hero"><div><p class="eyebrow">${t('version')}</p><h1>${t('fullDish')}</h1><p class="description">${t('desc')}</p>${meta()}<div class="tag-row"><span class="tag">${t('categories')[3]}</span><span class="tag">${t('categories')[5]}</span><span class="tag">${t('gluten')}</span></div><div class="path">${t('path').map((p,i)=>`${i?'<span aria-hidden="true">→</span>':''}<strong>${p}</strong>`).join('')}</div><a class="button hero-start" href="#cook">${t('start')} →</a></div><figure>${dishPhoto()}<figcaption>${aiLink(t('ai'),'photo-credit')}</figcaption></figure></section>${review()}</div><div class="recipe-bar"><div class="shell"><span class="recipe-context">${t('dish')}</span><div class="tabs" aria-label="${t('overview')}"><button type="button" id="tab-ingredients" data-section="ingredients">${t('ingredients')}</button><button type="button" id="tab-method" data-section="method">${t('steps')}</button></div><a href="#cook" class="button">${t('start')} →</a></div></div><div class="shell recipe-body"><section id="panel-ingredients" class="recipe-panel ingredients-panel"><div class="section-title"><h2>${t('ingredients')}</h2>${servings()}</div><p class="small">${t('ingredientTitle')} · <span class="serving-count">${state.servings}</span> ${t('servings')}</p>${ingredientPhoto()}<div class="ingredient-list-host" data-prefix="recipe">${ingredients('recipe')}</div><p class="small">${t('water')}</p><div class="teaching-note" style="margin-top:25px"><p class="eyebrow">${t('kitchenNote')}</p><h3>${t('prep')}</h3><p>${t('prepBody')}</p></div></section><section id="panel-method" class="recipe-panel"><h2>${t('methodTitle')}</h2><ol class="method-list">${t('stepTitles').map((title,i)=>`<li><div><h3>${title}</h3><p>${t('instructions')[i]}</p></div></li>`).join('')}</ol><div class="teaching-note"><p class="eyebrow">${t('practice')}</p><h3>${t('lessonTitle')}</h3><p>${t('lessonBody')}</p><a href="#cook" data-first-step>${t('lessonLink')} →</a><p class="margin-line">${t('seasoning')}</p></div><p class="small" style="margin-top:20px">${t('sourceFoot')}</p></section></div><div class="shell">${footer()}</div></main>`;applyTabs();}
function applyTabs(){if(route()!=='recipe')return;const tabs=app.querySelector('.tabs');if(wide.matches)tabs.removeAttribute('role');else tabs.setAttribute('role','tablist');['ingredients','method'].forEach(id=>{const tab=document.querySelector('#tab-'+id),panel=document.querySelector('#panel-'+id);panel.hidden=!wide.matches&&state.section!==id;if(wide.matches){['role','aria-selected','aria-controls','tabindex'].forEach(a=>tab.removeAttribute(a));['role','aria-labelledby'].forEach(a=>panel.removeAttribute(a));}else{tab.setAttribute('role','tab');tab.setAttribute('aria-selected',String(state.section===id));tab.setAttribute('aria-controls',panel.id);tab.tabIndex=state.section===id?0:-1;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);}});}
function remaining(){return state.timerEnd===null?state.timerRemaining:Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000));}
function timerMarkup(){const seconds=remaining();return `<button type="button" class="timer ${seconds===0?'time-up':''}" data-action="timer"><strong data-time>${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}</strong><span data-timer-label>${t(seconds===0?'timerDone':state.timerEnd?'timerPause':state.timerStarted?'timerResume':'timerStart')}</span></button>${state.timerStarted?button(t('timerReset'),'reset-timer','quiet'):''}<p class="small">${t('timerNote')}</p>`;}
function cueDiagram(){return `<div class="cue-picture"><svg class="cue-illustration" viewBox="0 0 150 108" role="img" aria-label="${t('cueTitle')}"><path d="M23 49v35q0 15 16 15h72q16 0 16-15V49M10 57h13m104 0h13" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="75" cy="49" rx="52" ry="15" fill="var(--blue-soft)" stroke="currentColor" stroke-width="2"/><g fill="none" stroke="currentColor" stroke-width="1.7"><ellipse cx="53" cy="47" rx="5" ry="3"/><ellipse cx="87" cy="54" rx="4" ry="2.5"/><ellipse cx="102" cy="44" rx="5" ry="3"/><path d="M49 28c-9-9 8-10 0-19M74 24c-9-9 8-10 0-19M100 28c-9-9 8-10 0-19"/></g></svg><div class="cue-label">${t('diagram')}</div></div>`;}
function renderCook(){const i=state.step;app.innerHTML=`<div class="cook-head"><div class="shell"><a href="#recipe" class="button quiet">← ${t('overview')}</a><div><span class="cook-heading">${t('dish')}</span><span class="small">${t('version')}</span></div>${button(t('ingredients'),'ingredients','secondary cook-mobile-ingredients')}</div></div><main id="content" class="shell cook-layout"><aside class="cook-sidebar"><div class="section-title"><h2>${t('ingredients')}</h2><span class="small">${state.servings} ${t('servings')}</span></div>${ingredientPhoto(true)}<div class="ingredient-list-host" data-prefix="wide">${ingredients('wide')}</div><p class="small">${t('pictureNote')}</p></aside><section class="cook-step"><div class="step-progress" aria-hidden="true">${[0,1,2,3].map(n=>`<span class="${n<=i?'done':''}"></span>`).join('')}</div><p class="eyebrow">${t('step')} ${i+1} ${t('of')} 4</p><h1>${t('stepTitles')[i]}</h1><p class="instruction">${t('instructions')[i]}</p>${i===0?`<div id="timer-area">${timerMarkup()}</div><section class="cue"><div class="cue-top">${cueDiagram()}<div><p class="eyebrow">${t('look')}</p><h2>${t('cueTitle')}</h2><p>${t('cueBody')}</p></div></div><details class="help"><summary>${t('help')}</summary><p>${t('tooHard')}</p><p>${t('nothing')}</p></details></section>`:`<div class="teaching-note" style="margin:24px 0"><p class="eyebrow">${t('kitchenNote')}</p><p style="margin-top:12px">${i===1?t('check'):t('seasoning')}</p>${state.timerStarted?`<div id="timer-area">${timerMarkup()}</div>`:''}</div>`}<div style="margin-top:24px">${review()}</div></section></main><footer class="cook-actions"><div class="shell">${button(t('previous'),'previous','secondary',i===0?'disabled':'')}${button(t(i===3?'finish':'next'),'next')}</div></footer>`;}
function renderComplete(){app.innerHTML=`<main id="content" class="shell"><section class="complete"><p class="eyebrow">${t('welcome')}</p><h1>${t('doneTitle')}</h1><p>${t('doneBody')}</p><a class="button" href="#recipe">${t('again')} →</a></section></main>`;}
function render(focus=false){networkObserver?.disconnect();header();
  if(tomatoRoute()||!['recipe','cook','complete'].includes(route())){
    document.querySelector('#navigation a[href="#recipe"]').href='#recipe/tomato';
    document.querySelector('#navigation a[href="#cook"]').href='#cook/tomato';
  }
  const pages=tomatoRoute()?{recipe:renderTomatoRecipe,cook:renderTomatoCook,complete:renderTomatoComplete}:{library:renderLibrary,network:renderNetwork,recipe:renderRecipe,cook:renderCook,complete:renderComplete};
  pages[route()]();if(focus){const branch=app.querySelector('[data-network-branch][aria-current=true]');if(location.hash.startsWith('#explore/branch/')&&branch?.getClientRects().length){branch.focus();return;}const detail=app.querySelector('#network-detail-title');const heading=detail||app.querySelector('h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});if(detail)document.querySelector('#network-detail').scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo(0,0);}}
function syncIngredients(){document.querySelectorAll('[data-ingredient]').forEach(input=>{input.checked=state.checked.has(Number(input.dataset.ingredient));});}
function refreshQuantities(){document.querySelectorAll('.ingredient-list-host').forEach(host=>{host.innerHTML=ingredients(host.dataset.prefix);});document.querySelectorAll('.serving-count').forEach(el=>el.textContent=state.servings);document.querySelectorAll('[data-action="less"]').forEach(el=>el.disabled=state.servings<=1);document.querySelectorAll('[data-action="more"]').forEach(el=>el.disabled=state.servings>=8);announce(`${state.servings} ${t('servings')}`);}
function selectSection(section){if(section===state.section)return;state.sectionScroll[state.section]=window.scrollY;state.section=section;applyTabs();const bar=document.querySelector('.recipe-bar');const sectionTop=document.querySelector('.recipe-body').getBoundingClientRect().top+window.scrollY-bar.getBoundingClientRect().height;window.scrollTo({top:state.sectionScroll[section]||sectionTop,behavior:'instant'});}
function openAI(){
  const modal=document.querySelector('#ai-dialog');
  document.querySelector('#ai-title').textContent=t('aiTitle');
  document.querySelector('#close-ai').textContent=t('close');
  document.querySelector('#ai-content').innerHTML=`<p>${t('aiIntro')}</p><p>${t('aiWhy')}</p><p>${t('aiLimits')}</p><h3>${t('aiChecksTitle')}</h3><p>${t('aiChecks')}</p><p>${t('aiNoBlanket')}</p><div class="status-detail"><p class="eyebrow">${t('sampleStatus')} · ${t('version')}</p>${verificationKeys(recipeVerification).map(key=>`<p><strong>${t(key)}</strong></p>`).join('')}<p>${t('statusExplanation')}</p></div><h3>${t('aiLink')}</h3><p>${t('aiOther')}</p>`;
  if(route()==='network')document.querySelector('#ai-content .status-detail').innerHTML=`<p>${networkText('imageStatus')}</p>`;
  if(tomatoRoute())document.querySelector('#ai-content .status-detail').innerHTML=`<p>${tt('imageNote')}</p>`;
  modal.showModal();
}
function openIngredients(){document.querySelector('#dialog-title').textContent=t('ingredients');document.querySelector('#close-dialog').textContent=t('close');document.querySelector('#dialog-content').innerHTML=`<p class="small">${state.servings} ${t('servings')}</p>${ingredientPhoto()}<div class="ingredient-list-host" data-prefix="sheet">${ingredients('sheet')}</div>`;dialog.showModal();}
document.addEventListener('click',event=>{const category=event.target.closest('[data-category]');if(category){state.category=category.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===state.category)));updateResults();return;}if(event.target.closest('[data-open-ingredients]'))state.section='ingredients';if(event.target.closest('[data-first-step]'))state.step=0;const tab=event.target.closest('[data-section]');if(tab){selectSection(tab.dataset.section);return;}const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;
  if(action==='about-ai')openAI();
  if(action==='clear'){state.category='all';state.query='';render(true);}
  if(action==='less'||action==='more'){state.servings=Math.max(1,Math.min(8,state.servings+(action==='more'?1:-1)));refreshQuantities();}
  if(action==='ingredients')openIngredients();
  if(action==='previous'||action==='next'){if(action==='next'&&state.step===3){state.timerEnd=null;state.timerRemaining=720;state.timerStarted=false;state.step=0;location.hash='complete';}else{state.step+=action==='next'?1:-1;render(true);}}
  if(action==='timer'){if(remaining()===0)return;if(state.timerEnd){state.timerRemaining=remaining();state.timerEnd=null;}else{state.timerEnd=Date.now()+state.timerRemaining*1000;state.timerStarted=true;}document.querySelector('#timer-area').innerHTML=timerMarkup();document.querySelector('[data-action="timer"]').focus();}
  if(action==='reset-timer'){state.timerEnd=null;state.timerRemaining=720;state.timerStarted=false;document.querySelector('#timer-area').innerHTML=timerMarkup();document.querySelector('[data-action="timer"]').focus();}
});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.query=event.target.value;updateResults();}});
document.addEventListener('change',event=>{if(event.target.matches('[data-ingredient]')){const id=Number(event.target.dataset.ingredient);event.target.checked?state.checked.add(id):state.checked.delete(id);syncIngredients();}});
document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-section]');if(!tab||wide.matches||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const target=event.key==='Home'?'ingredients':event.key==='End'?'method':state.section==='ingredients'?'method':'ingredients';selectSection(target);document.querySelector('#tab-'+target).focus({preventScroll:true});});
document.querySelector('#close-ai').addEventListener('click',()=>document.querySelector('#ai-dialog').close());
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();const main=document.querySelector('#content');main.setAttribute('tabindex','-1');main.focus();main.scrollIntoView();});
document.querySelector('#language').addEventListener('click',()=>{state.lang=state.lang==='en'?'de':'en';render();});
document.querySelector('#theme').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';header();});
bindTomatoEvents();
window.addEventListener('hashchange',()=>{if(document.querySelector('#ai-dialog').open)document.querySelector('#ai-dialog').close();if(dialog.open)dialog.close();render(true);});
wide.addEventListener('change',()=>{const active=document.activeElement;const sheetClosed=wide.matches&&dialog.open;if(sheetClosed)dialog.close();applyTabs();if(sheetClosed||active?.closest('[hidden]')||wide.matches&&active?.matches('[data-section]')||!wide.matches&&active?.closest('.cook-sidebar')){const heading=app.querySelector('h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});}});
setInterval(()=>{const seconds=remaining();document.querySelectorAll('[data-time]').forEach(el=>el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`);if(state.timerEnd&&seconds===0){state.timerRemaining=0;state.timerEnd=null;document.querySelectorAll('[data-timer-label]').forEach(el=>el.textContent=t('timerDone'));document.querySelectorAll('.timer').forEach(el=>el.classList.add('time-up'));announce(t('timerEnded'));}},1000);
render();
